css:
[data-bz-section="pg-faq"] .bz-headingblock h2 { margin-bottom: 40px; }
[data-bz-section="pg-faq"] .bz-faqs { gap: 0; }
[data-bz-section="pg-faq"] .bz-faq { background: none; border: 0; border-bottom: 1px solid #eee; border-radius: 0; padding: 20px 0; }
[data-bz-section="pg-faq"] .bz-faq:first-child { padding-top: 0; }
[data-bz-section="pg-faq"] .bz-faq:last-child { border-bottom: 0; }
[data-bz-section="pg-faq"] .bz-faq summary { font: 700 17px / 1.4 var(--font-heading); color: var(--ink); list-style: none; }
[data-bz-section="pg-faq"] .bz-faq summary::-webkit-details-marker { display: none; }
[data-bz-section="pg-faq"] .bz-faq__a { font-size: 15px; line-height: 24px; color: var(--copy); margin-top: 10px; }
[data-bz-section="pg-faq"] .bz-faq::details-content { content-visibility: visible; }

js:
// The design shows every answer open. Open them once the page is live; without script (or in the editor) they stay a normal accordion.
document.querySelectorAll('[data-bz-section="pg-faq"] details.bz-faq').forEach(function (item) {
  item.open = true;
  var summary = item.querySelector('summary');
  if (summary) summary.addEventListener('click', function (event) { event.preventDefault(); });
});
